## The map editor's shared core: symmetry orbits, generated-map validation, and
## the standalone renderer.
##
## TWO GENERATED BASELINES live in tests/fixtures and are regenerated by running
## this module with `CTF_REGEN_MAP_BASELINE=1`:
##
##     CTF_REGEN_MAP_BASELINE=1 nim c -d:release -r tests/test_map_editor_core.nim
##
## Both were captured on the RECTANGULAR board and could not survive the hex
## conversion: `map-validation-baseline.tsv` carried an `endzone` column whose
## tokens (column / square) name deleted geometries and a `layout` column whose
## tokens (corners / plus) name deleted C4 layouts, and every render hash was
## the CRC of a 1235x659 image. Regenerating is the only honest move; hand-
## editing rows to make an assertion pass is not.
import
  helpers,
  std/[math, os, sets, strutils, unittest],
  crunchy/crc32,
  pixie,
  pixie/fileformats/png,
  ctf/[map_pool, sim],
  "../tools/map_render"

const
  ValidationBaselinePath =
    currentSourcePath.parentDir / "fixtures" / "map-validation-baseline.tsv"
  RenderHashPath =
    currentSourcePath.parentDir / "fixtures" / "pool-render-hashes.txt"
  Regenerate = "CTF_REGEN_MAP_BASELINE"
  ## The seeds the validation baseline covers. 2-team only: hex Stage 2
  ## generates nothing else (`generateMapAttempt` raises for any other count).
  BaselineSeeds = 1000 .. 1199

proc poolMap(index: int): CtfMap =
  generateMapAttempt(
    MapPoolSeeds[index],
    MapGenOverrides(windows: -1, pits: -1, pitDensity: -1),
  )

proc poolRenderOptions(maxDimension = 0): MapRenderOptions =
  MapRenderOptions(
    maxDimension: maxDimension,
    overlays: {overlayProtected, overlayPickups},
    pickupKinds: {pickupMedKitActive, pickupMedKitCandidate},
  )

proc surroundingsMap(symmetry: MapSymmetry): CtfMap =
  ## A tiny hand-built board in the hexagon's own aspect (101 x 117 is within a
  ## pixel of sqrt(3)/2), with one stone block well inside the hull.
  const
    Width = 101
    Height = 117
  CtfMap(
    width: Width,
    height: Height,
    center: MapPoint(x: Width div 2, y: Height div 2),
    flagRing: 5,
    captureClear: 15,
    spawnClearW: 3,
    spawnClearH: 3,
    homeDepth: 700,
    symmetry: symmetry,
    layout: layoutHex2,
    leftObstacles: @[rectShape(MapRect(x: 20, y: 50, w: 7, h: 11))],
  )

proc checkSymmetricSurroundings(gameMap: CtfMap, source: MapPoint) =
  ## A coordinate orbit is only useful when it carries the same terrain
  ## with it. Sample both stone and floor so an empty patch cannot make this
  ## fairness assertion pass vacuously.
  let
    obstacles = buildArenaObstacles(gameMap)
    wall = rasterizeRestWallMask(
      gameMap,
      obstacles,
      proc (x, y: int): bool = mapProtectedFloorAt(gameMap, x, y),
    )
    sourceOrbit = gameMap.symmetryImages(source)
    board = gameMap.mapBoard()
  var sawWall, sawFloor: bool
  for dy in -8 .. 8:
    for dx in -8 .. 8:
      let
        sample = MapPoint(x: source.x + dx, y: source.y + dy)
        sampleOrbit = gameMap.symmetryImages(sample)
        sourceIsWall = wall[sample.y * gameMap.width + sample.x]
      ## Every sample is real playfield, not hull: on a hexagon a window that
      ## strayed into the void would read "wall" everywhere and pass vacuously.
      check board.insideHex(sample.x, sample.y)
      check sampleOrbit.len == sourceOrbit.len
      if sourceIsWall: sawWall = true
      else: sawFloor = true
      for image in sampleOrbit:
        check wall[image.y * gameMap.width + image.x] == sourceIsWall
  check sawWall
  check sawFloor

suite "map editor core":
  test "symmetry images form exact deduplicated integer orbits":
    ## The two pixel-exact 2-team groups. `symRot90` is gone with C4, which is
    ## not a subgroup of D6, so a quarter-turn orbit no longer exists to test.
    var gameMap = CtfMap(
      width: 11, height: 9, symmetry: symMirrorHex, layout: layoutHex2)
    check gameMap.symmetryImages(MapPoint(x: 2, y: 3)) == @[
      MapPoint(x: 2, y: 3),
      MapPoint(x: 8, y: 3),
    ]
    check gameMap.symmetryImages(MapRect(x: 1, y: 2, w: 3, h: 2)) == @[
      MapRect(x: 1, y: 2, w: 3, h: 2),
      MapRect(x: 7, y: 2, w: 3, h: 2),
    ]
    check gameMap.symmetryImages(MapPoint(x: 5, y: 4)) == @[
      MapPoint(x: 5, y: 4),
    ]
    gameMap.width = 10
    check gameMap.symmetryImages(MapRect(x: 4, y: 2, w: 2, h: 3)) == @[
      MapRect(x: 4, y: 2, w: 2, h: 3),
    ]

    gameMap = CtfMap(
      width: 11, height: 9, symmetry: symRot180, layout: layoutHex2)
    check gameMap.symmetryImages(MapPoint(x: 2, y: 3)) == @[
      MapPoint(x: 2, y: 3),
      MapPoint(x: 8, y: 5),
    ]
    check gameMap.symmetryImages(MapRect(x: 1, y: 2, w: 3, h: 2)) == @[
      MapRect(x: 1, y: 2, w: 3, h: 2),
      MapRect(x: 7, y: 5, w: 3, h: 2),
    ]
    check gameMap.symmetryImages(MapPoint(x: 5, y: 4)) == @[
      MapPoint(x: 5, y: 4),
    ]
    check gameMap.symmetryImages(MapRect(x: 4, y: 3, w: 3, h: 3)) == @[
      MapRect(x: 4, y: 3, w: 3, h: 3),
    ]

    ## The 4-team group IS expressible — it is V4, two perpendicular mirrors
    ## and their product — and its orbit is four distinct images.
    gameMap = CtfMap(
      width: 11, height: 9, symmetry: symKlein4, layout: layoutHex4)
    check gameMap.symmetryImages(MapPoint(x: 2, y: 3)) == @[
      MapPoint(x: 2, y: 3),
      MapPoint(x: 2, y: 5),
      MapPoint(x: 8, y: 3),
      MapPoint(x: 8, y: 5),
    ]
    ## ...and a rotation that is NOT exact on pixels is refused outright rather
    ## than rounded, which is the whole reason those groups wait for Stage 2b.
    gameMap = CtfMap(
      width: 11, height: 9, symmetry: symRot120, layout: layoutHex3)
    expect CtfError:
      discard gameMap.symmetryImages(MapRect(x: 1, y: 2, w: 3, h: 2))

  test "symmetry images carry the original wall surroundings":
    for symmetry in [symMirrorHex, symRot180]:
      surroundingsMap(symmetry).checkSymmetricSurroundings(
        MapPoint(x: 23, y: 55)
      )

  test "rectangle expansion matches generated finalized trenches":
    for symmetry in ["mirror", "rot180"]:
      let gameMap = generateMapAttempt(
        1001,
        MapGenOverrides(
          size: "small",
          symmetry: symmetry,
          windows: -1,
          pits: 2,
          pitDensity: -1,
        ),
      )
      check gameMap.trenches.len == 2
      var trenchRects: seq[MapRect]
      for t in gameMap.trenches:
        trenchRects.add shapeAsRect(t)
      check gameMap.symmetryImages(shapeAsRect(gameMap.trenches[0])) ==
        trenchRects

  test "generated-map validation matches the recorded baseline":
    ## The per-seed verdicts of `validateGeneratedMap` over a fixed seed range,
    ## so a validator refactor that changes ANY verdict shows up as a diff
    ## rather than as a silently different map pool.
    var rows = @[
      "# validateGeneratedMap baseline for the HEXAGONAL arena. GENERATED —",
      "# regenerate with:",
      "#   CTF_REGEN_MAP_BASELINE=1 nim c -d:release -r " &
        "tests/test_map_editor_core.nim",
      "# 2-team only: hex Stage 2 generates no other team count.",
      "seed\tsize\tsymmetry\treason",
    ]
    for seed in BaselineSeeds:
      let gameMap = generateMapAttempt(
        seed, MapGenOverrides(windows: -1, pits: -1, pitDensity: -1))
      var size = ""
      for cls in HexSizeClass:
        if HexSizes[cls] == (gameMap.width, gameMap.height):
          size = HexClassNames[cls]
      rows.add $seed & "\t" & size & "\t" & $gameMap.symmetry & "\t" &
        validateGeneratedMap(gameMap)
    let text = rows.join("\n") & "\n"
    if getEnv(Regenerate) == "1":
      writeFile(ValidationBaselinePath, text)
    check text == readFile(ValidationBaselinePath)

    ## The baseline is only worth pinning if it is not all one answer: it has
    ## to carry real rejections AND real passes, over more than one class.
    var passes, failures = 0
    var sizes, symmetries, reasons = initHashSet[string]()
    for line in text.splitLines():
      if line.len == 0 or line[0] == '#' or line.startsWith("seed\t"):
        continue
      let fields = line.split('\t')
      check fields.len == 4
      sizes.incl fields[1]
      symmetries.incl fields[2]
      if fields[3].len == 0:
        inc passes
      else:
        inc failures
        reasons.incl fields[3].split(" at ")[0]
    check passes + failures == BaselineSeeds.len
    check passes > 0
    check failures > 0
    check sizes.len >= 3
    check symmetries == ["symMirrorHex", "symRot180"].toHashSet()
    check reasons.len > 0

    ## And the SUMMARY path agrees with the FULL diagnostics path on every
    ## seed it is spot-checked against — two code paths, one verdict.
    for seed in [BaselineSeeds.a, BaselineSeeds.a + 57, BaselineSeeds.b]:
      let gameMap = generateMapAttempt(
        seed, MapGenOverrides(windows: -1, pits: -1, pitDensity: -1))
      check mapDiagnostics(gameMap).reason == validateGeneratedMap(gameMap)

  test "every curated map spec round-trips byte-identically":
    for index in 0 ..< MapPoolSeeds.len:
      let
        gameMap = poolMap(index)
        spec = mapSpecJson(gameMap)
        rebuilt = mapFromSpecJson(spec)
      check mapSpecJson(rebuilt) == spec
      check rebuilt == gameMap

  test "shared pool rendering matches the recorded images":
    var hashes: seq[string]
    for index in 0 ..< MapPoolSeeds.len:
      let rendered = renderMap(poolMap(index), poolRenderOptions())
      ## The render really is of THIS map, not a stale global's.
      check rendered.image.width == poolMap(index).width
      check rendered.image.height == poolMap(index).height
      hashes.add "0x" & toHex(crc32(rendered.image.encodePng()), 8)
    let text = "# CRC32 of the pool renders, one per MapPoolSeeds index.\n" &
      "# GENERATED — regenerate with:\n" &
      "#   CTF_REGEN_MAP_BASELINE=1 nim c -d:release -r " &
      "tests/test_map_editor_core.nim\n" & hashes.join("\n") & "\n"
    if getEnv(Regenerate) == "1":
      writeFile(RenderHashPath, text)
    check text == readFile(RenderHashPath)

  test "maxDimension uses one exact non-upscaling render scale":
    let
      gameMap = poolMap(0)
      rendered = renderMap(gameMap, poolRenderOptions(maxDimension = 160))
      expectedScale = 160.0 / float(max(gameMap.width, gameMap.height))
      summary = mapDiagnostics(gameMap)
      withMasks = mapDiagnostics(
        gameMap,
        {diagnosticWallMasks, diagnosticCorridorOpen, diagnosticReachable},
      )
    var reachabilityOptions = poolRenderOptions(maxDimension = 160)
    reachabilityOptions.overlays.incl overlayReachability
    let reachabilityRender = renderMap(gameMap, reachabilityOptions)
    check abs(rendered.renderScale - expectedScale) < 1e-12
    check rendered.image.width == int(ceil(float(gameMap.width) * expectedScale))
    check rendered.image.height ==
      int(ceil(float(gameMap.height) * expectedScale))
    check reachabilityRender.image.width == rendered.image.width
    check reachabilityRender.image.height == rendered.image.height
    check summary.maxWall.len == 0
    check summary.minWall.len == 0
    check summary.corridorOpen.len == 0
    check summary.reachable.len == 0
    check withMasks.maxWall.len == gameMap.width * gameMap.height
    check withMasks.minWall.len == gameMap.width * gameMap.height
    check withMasks.corridorOpen.len == gameMap.width * gameMap.height
    check withMasks.reachable.len == gameMap.width * gameMap.height

  test "rendering arbitrary maps is independent of installed globals":
    let
      widthBefore = MapWidth
      heightBefore = MapHeight
      obstaclesBefore = ArenaObstacles
      twoTeamMap = poolMap(0)
      ## Hex Stage 2 generates 2-team boards only, so the 4-team render runs on
      ## the hand-authored Klein-four hexagon (helpers.hexTeamMap).
      fourTeamMap = hexTeamMap()
    check fourTeamMap.teamCount() == 4
    discard renderMap(twoTeamMap, poolRenderOptions(maxDimension = 160))
    discard renderMap(fourTeamMap, poolRenderOptions(maxDimension = 160))
    check MapWidth == widthBefore
    check MapHeight == heightBefore
    check ArenaObstacles == obstaclesBefore
